def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    cmap = {3: 8, 6: 3, 8: 7, 7: 6}
    # Each solid 2x2 square has four diagonal marker rays pointing outward.
    for br in range(h - 1):
        for bc in range(w - 1):
            if not all(grid[r][c] == 2 for r in (br, br + 1) for c in (bc, bc + 1)):
                continue
            for r, c, dr, dc in (
                (br - 1, bc - 1, -1, -1),
                (br - 1, bc + 2, -1, 1),
                (br + 2, bc - 1, 1, -1),
                (br + 2, bc + 2, 1, 1),
            ):
                if 0 <= r < h and 0 <= c < w and grid[r][c] in cmap:
                    color = cmap[grid[r][c]]
                    while 0 <= r < h and 0 <= c < w:
                        if out[r][c] != 2:
                            out[r][c] = color
                        r += dr
                        c += dc
    return out
